"use client";

import React from 'react';
import { motion } from 'framer-motion';
import Image from 'next/image';

interface AnimatedCDProps {
  imageUrl?: string;
  className?: string;
}

export function AnimatedCD({ imageUrl = '/anuu.jpeg', className = '' }: AnimatedCDProps) {
  return (
    <motion.div
      initial={{ opacity: 0, y: 50 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true, margin: "-100px" }}
      transition={{ duration: 0.8, ease: "easeOut" }}
      className={`relative flex items-center justify-center p-8 ${className}`}
    >
      {/* Animated gradient background with glassmorphism */}
      <div className="absolute inset-0 bg-gradient-to-br from-primary/30 via-accent/20 to-secondary/30 rounded-full blur-3xl opacity-50 mix-blend-screen animate-pulse duration-[3000ms]" />
      
      {/* Floating effect wrapper */}
      <motion.div
        animate={{ y: [0, -15, 0] }}
        transition={{ repeat: Infinity, duration: 4, ease: "easeInOut" }}
        className="relative z-10"
      >
        <motion.div
          className="relative w-64 h-64 md:w-80 md:h-80 lg:w-96 lg:h-96 rounded-full cursor-pointer group"
          whileHover={{ scale: 1.05 }}
          style={{ perspective: 1000 }}
        >
          {/* 3D Container to apply tilts on hover */}
          <motion.div 
            className="w-full h-full relative"
            whileHover={{ rotateX: 10, rotateY: -10 }}
            transition={{ type: "spring", stiffness: 300, damping: 20 }}
          >
            {/* Neon Glow & Shadows */}
            <div className="absolute inset-0 rounded-full shadow-[0_0_40px_rgba(255,255,255,0.1)] group-hover:shadow-[0_0_80px_var(--primary)] transition-shadow duration-500" />
            
            {/* CD Base with glassmorphism */}
            <div className="absolute inset-0 rounded-full border-[1px] border-white/20 bg-black/40 backdrop-blur-xl overflow-hidden shadow-2xl flex items-center justify-center">
              
              {/* Infinite Rotation for CD contents */}
              <motion.div
                animate={{ rotate: 360 }}
                transition={{ repeat: Infinity, duration: 8, ease: "linear" }}
                className="w-full h-full relative flex items-center justify-center"
              >
                {/* CD Tracks (Concentric circles) */}
                <div className="absolute inset-2 rounded-full border border-white/10" />
                <div className="absolute inset-4 rounded-full border border-white/10" />
                <div className="absolute inset-8 rounded-full border border-white/5" />
                <div className="absolute inset-12 rounded-full border border-white/5" />
                <div className="absolute inset-16 rounded-full border border-white/5" />
                <div className="absolute inset-20 rounded-full border border-white/5" />
                
                {/* Album Art (Image inside CD) */}
                <div className="absolute inset-0 rounded-full overflow-hidden opacity-50 mix-blend-overlay">
                  <Image 
                    src={imageUrl} 
                    alt="Album Art" 
                    fill 
                    className="object-cover"
                  />
                </div>

                {/* Rainbow Reflection/Shine overlay to simulate CD reflection */}
                <div 
                  className="absolute inset-0 rounded-full opacity-40 mix-blend-color-dodge"
                  style={{
                    background: 'conic-gradient(from 0deg, transparent 0deg, rgba(255,0,0,0.2) 60deg, rgba(255,255,0,0.2) 120deg, rgba(0,255,0,0.2) 180deg, rgba(0,255,255,0.2) 240deg, rgba(0,0,255,0.2) 300deg, transparent 360deg)'
                  }}
                />
                
                {/* High gloss diagonal shine */}
                <div className="absolute inset-0 bg-gradient-to-tr from-transparent via-white/40 to-transparent rotate-45 mix-blend-overlay" />
                
                {/* CD Inner Hole Background */}
                <div className="relative w-20 h-20 md:w-24 md:h-24 rounded-full bg-gradient-to-br from-gray-900 to-black border-2 border-white/30 shadow-[inset_0_0_10px_rgba(0,0,0,0.8)] flex items-center justify-center z-20">
                  {/* CD Spindle Hole */}
                  <div className="w-5 h-5 md:w-6 md:h-6 rounded-full bg-background border border-white/10 shadow-inner" />
                </div>
              </motion.div>
            </div>
          </motion.div>
        </motion.div>
      </motion.div>
    </motion.div>
  );
}
